ReplacementContent:
".parallax-bg-layer {
  position: fixed;
  top: -5%;
  left: -5%;
  width: 110%;
  height: 110%;
  z-index: -2; /* 位于最底层 */
  will-change: transform;
  transition: transform 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  pointer-events: none;
  overflow: hidden;
}

/* 宽高比自适应容器，确保 clean 背景底图与 4角时钟、天秤 cutouts 保持等比例视口裁剪，实现像素级重合 */
.bg-aspect-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  will-change: transform;
}

/* 移动端 (941/1672 = 0.5628) cover 填充算法 */
@media screen and (max-width: 819px) {
  @media (min-aspect-ratio: 941/1672) {
    .bg-aspect-container {
      width: 100%;
      height: 177.68vw;
    }
  }
  @media (max-aspect-ratio: 941/1672) {
    .bg-aspect-container {
      height: 100%;
      width: 56.28vh;
    }
  }
}

/* 宽屏桌面端 (1672/941 = 1.7768) cover 填充算法 */
@media screen and (min-width: 820px) {
  @media (min-aspect-ratio: 1672/941) {
    .bg-aspect-container {
      width: 100%;
      height: 56.28vw;
    }
  }
  @media (max-aspect-ratio: 1672/941) {
    .bg-aspect-container {
      height: 100%;
      width: 177.68vh;
    }
  }
}

.bg-base-image {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('bg_mobile_clean.webp');
  background-size: 100% 100%; /* 因为父级容器已锁定宽高比，这里使用百分比铺满，绝不拉伸变形 */
  background-position: center;
  background-repeat: no-repeat;
}"

